        ActionType.LayerVisibility => "layer.visibility",
        ActionType.LayerRestart => "layer.restart",
        ActionType.LayerFreezeOnAir => "layer.freeze_on_air",
        ActionType.LayerCopyStyle => "layer.copy_style",
        ActionType.LayerOpacity => "layer.opacity",
        ActionType.LayerClip => "layer.clip",
        ActionType.FilterToggle => "filter.toggle",
        ActionType.FilterSet => "filter.set",
        ActionType.LayerFraming => "layer.framing",
        ActionType.LayerNudge => "layer.nudge",
        ActionType.AudioMute => "audio.mute",
        ActionType.AudioVolume => "audio.volume",
        ActionType.AudioMonitor => "audio.monitor",
        ActionType.AudioMonitorBus => "audio.monitor_bus",
        ActionType.AudioMonitorSend => "audio.monitor_send",
        ActionType.AudioAppVolume => "audio.app_volume",
