    public Task<ScenePreviousResult> ScenePreviousAsync(CancellationToken cancellationToken = default) =>
        InvokeAsync<ScenePreviousResult>("scene.previous", cancellationToken);

    /// <summary>
    /// Pin the vertical canvas: Keeps the vertical canvas on one scene while the main (landscape) canvas switches scenes, or lets it follow the scene on air again. pin keeps it on the scene; follow lets it follow the scene on air (no scene needed); toggle pins it to the scene, or lets it follow again when it's already pinned there (with no scene, a pinned canvas follows again). A scene with no vertical layout shows its horizontal layout, fitted. Needs the vertical canvas (Settings › Video › Vertical canvas); while it's off, the choice is kept for when it's back on. If the pinned scene is deleted, the vertical canvas follows the scene on air again.
    /// </summary>
    /// <param name="parameters">The action's parameters.</param>
    /// <param name="cancellationToken">Stops waiting for Studio's answer.</param>
    /// <returns>What the action did.</returns>
