    public Task<UpdateState> UpdateInstallAsync(CancellationToken cancellationToken = default) =>
        InvokeAsync<UpdateState>("update.install", cancellationToken);

    /// <summary>
    /// Raw request: The escape hatch: commits scene-model commands as one transaction, all or nothing, exactly as Studio's own panels do (see the model's command reference). Changes made this way aren't undo steps.
    /// </summary>
    /// <param name="parameters">The action's parameters.</param>
    /// <param name="cancellationToken">Stops waiting for Studio's answer.</param>
    /// <returns>What the action did.</returns>
    public Task<RawTransactionResult> RawTransactionAsync(RawTransactionParams parameters, CancellationToken cancellationToken = default) =>
        InvokeAsync<RawTransactionParams, RawTransactionResult>("raw.transaction", parameters, cancellationToken);

